#include <vector>
using namespace std;class Solution{long long f(vector<long long>&a,vector<long long>&t,int l,int r,long long lo,long long hi){if(r-l<=1)return 0;int m=(l+r)/2;long long c=f(a,t,l,m,lo,hi)+f(a,t,m,r,lo,hi);int p=m,q=m;for(int i=l;i<m;i++){while(p<r&&a[p]-a[i]<lo)p++;while(q<r&&a[q]-a[i]<=hi)q++;c+=q-p;}int i=l,j=m,k=l;while(i<m||j<r)t[k++]=(j==r||(i<m&&a[i]<=a[j]))?a[i++]:a[j++];for(i=l;i<r;i++)a[i]=t[i];return c;}public:int countRangeSum(vector<int>&nums,int lower,int upper){vector<long long>a(nums.size()+1),t(a.size());for(int i=0;i<nums.size();i++)a[i+1]=a[i]+nums[i];return f(a,t,0,a.size(),lower,upper);}};
